//! Axum HTTP/gRPC-Web host for the zeroclaw plugin schema.
//!
//! Serves the plugin-owned schema JSON on:
//!   - native gRPC over Unix socket `/run/opdbus/zeroclaw-grpc.sock`
//!   - HTTP/1.1 + gRPC-Web on TCP `0.0.0.0:8090` (configurable via D-Bus)
//!
//! The schema itself is never generated here; it is read from
//! `/dev/shm/opdbus/schemas/zeroclaw.json` written by the zeroclaw plugin.

use std::net::SocketAddr;
use std::path::PathBuf;
use std::pin::Pin;
use std::sync::Arc;

use async_stream::stream;
use axum::Router;
use tokio::sync::mpsc;
use tonic::{Request as TonicRequest, Response as TonicResponse, Status};
use tower_http::cors::{Any, CorsLayer};
use tracing::info;

use crate::dbus_object::{register_zeroclaw_host_object, ZeroclawAxumHostObject};
use crate::schema_loader::{SchemaLoader, SchemaReloadEvent};
use crate::tracing::{GhostbridgeTraceLayer, TraceContext};

use crate::proto::zeroclaw::{
    zeroclaw_service_server::{ZeroclawService, ZeroclawServiceServer},
    GetSchemaRequest, SchemaEvent, SchemaResponse, WatchSchemaRequest,
};

const DEFAULT_UNIX_SOCKET: &str = "/run/opdbus/zeroclaw-grpc.sock";
const DEFAULT_BIND_ADDR: &str = "0.0.0.0:8090";
const DEFAULT_SCHEMA_PATH: &str = "/dev/shm/opdbus/schemas/zeroclaw.json";

/// Runtime configuration for the zeroclaw Axum host.
#[derive(Clone, Debug)]
pub struct ServerConfig {
    pub schema_path: PathBuf,
    pub unix_socket: PathBuf,
    pub bind_addr: String,
}

impl Default for ServerConfig {
    fn default() -> Self {
        Self {
            schema_path: PathBuf::from(DEFAULT_SCHEMA_PATH),
            unix_socket: PathBuf::from(DEFAULT_UNIX_SOCKET),
            bind_addr: DEFAULT_BIND_ADDR.to_string(),
        }
    }
}

impl ServerConfig {
    /// Load configuration from environment variables, falling back to defaults.
    pub fn from_env() -> Self {
        Self {
            schema_path: PathBuf::from(
                std::env::var("ZEROCLAW_SCHEMA_PATH")
                    .unwrap_or_else(|_| DEFAULT_SCHEMA_PATH.to_string()),
            ),
            unix_socket: PathBuf::from(
                std::env::var("ZEROCLAW_UNIX_SOCKET")
                    .unwrap_or_else(|_| DEFAULT_UNIX_SOCKET.to_string()),
            ),
            bind_addr: std::env::var("ZEROCLAW_BIND_ADDR")
                .unwrap_or_else(|_| DEFAULT_BIND_ADDR.to_string()),
        }
    }
}

/// Shared state for the gRPC service handlers.
#[derive(Clone)]
struct ZeroclawGrpcService {
    loader: Arc<SchemaLoader>,
}

#[tonic::async_trait]
impl ZeroclawService for ZeroclawGrpcService {
    type WatchSchemaStream =
        Pin<Box<dyn tokio_stream::Stream<Item = Result<SchemaEvent, Status>> + Send>>;

    async fn get_schema(
        &self,
        request: TonicRequest<GetSchemaRequest>,
    ) -> Result<TonicResponse<SchemaResponse>, Status> {
        let context = request
            .extensions()
            .get::<TraceContext>()
            .cloned()
            .unwrap_or_else(|| TraceContext::from_tonic_metadata(request.metadata()));

        let schema_json = self.loader.get().await.to_string();
        let mut response = TonicResponse::new(SchemaResponse {
            schema_json,
            trace_id: context.trace_id.clone(),
            footprint: context.footprint.clone(),
        });
        inject_trace_metadata(&mut response, &context);
        Ok(response)
    }

    async fn watch_schema(
        &self,
        _request: TonicRequest<WatchSchemaRequest>,
    ) -> Result<TonicResponse<Self::WatchSchemaStream>, Status> {
        let mut reload_rx = self.loader.reload_tx().subscribe();
        let loader = self.loader.clone();

        let initial = loader.get().await;
        let stream = stream! {
            yield Ok(SchemaEvent {
                schema_json: initial.to_string(),
                event_type: "initial".to_string(),
            });

            while let Ok(SchemaReloadEvent { event_type }) = reload_rx.recv().await {
                let schema_json = loader.get().await.to_string();
                yield Ok(SchemaEvent {
                    schema_json,
                    event_type,
                });
            }
        };

        Ok(TonicResponse::new(Box::pin(stream)))
    }
}

fn inject_trace_metadata<T>(response: &mut TonicResponse<T>, context: &TraceContext) {
    if let (Ok(trace_id), Ok(footprint)) = (context.trace_id.parse(), context.footprint.parse()) {
        response
            .metadata_mut()
            .insert("x-ghostbridge-trace-id", trace_id);
        response
            .metadata_mut()
            .insert("x-ghostbridge-footprint", footprint);
    }
}

/// Build the axum `Router` that serves the gRPC service over HTTP/gRPC-Web.
pub fn build_axum_app(loader: Arc<SchemaLoader>) -> Router {
    let service = ZeroclawGrpcService { loader };
    let grpc_service = tonic_web::enable(ZeroclawServiceServer::new(service));
    let routes = tonic::service::Routes::new(grpc_service);

    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    routes
        .into_axum_router()
        .layer(cors)
        .layer(GhostbridgeTraceLayer::new())
}

/// Build the tonic `Routes` used for the native-gRPC Unix socket side.
fn build_tonic_routes(loader: Arc<SchemaLoader>) -> tonic::service::Routes {
    let service = ZeroclawGrpcService { loader };
    let grpc_service = tonic_web::enable(ZeroclawServiceServer::new(service));
    tonic::service::Routes::new(grpc_service)
}

/// Run the zeroclaw Axum host.
///
/// Returns only when both listeners exit (which should not happen under normal
/// operation).
pub async fn run_zeroclaw_server(config: ServerConfig) -> anyhow::Result<()> {
    let loader = Arc::new(SchemaLoader::new(&config.schema_path)?);

    // Channel for D-Bus-triggered rebind requests. Only `SchemaPath` changes are
    // applied live; `BindAddr` changes are recorded and honored on the next
    // restart.
    let (rebind_tx, mut rebind_rx) = mpsc::channel::<String>(4);

    // D-Bus object for runtime configuration.
    let dbus_object = ZeroclawAxumHostObject::new(loader.clone(), rebind_tx)?;
    let _dbus_connection = register_zeroclaw_host_object(dbus_object).await?;

    // SIGHUP reload watcher.
    let _sighup_handle = loader.clone().watch_sighup();

    // Unix socket listener for native gRPC.
    let unix_socket = config.unix_socket.clone();
    if let Some(parent) = unix_socket.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let _ = std::fs::remove_file(&unix_socket);
    let unix_listener = tokio::net::UnixListener::bind(&unix_socket)?;
    info!(path = %unix_socket.display(), "zeroclaw native gRPC listening on Unix socket");

    let unix_incoming = tokio_stream::wrappers::UnixListenerStream::new(unix_listener);

    let tonic_server = tonic::transport::Server::builder()
        .add_routes(build_tonic_routes(loader.clone()))
        .serve_with_incoming(unix_incoming);

    // TCP listener for HTTP + gRPC-Web.
    let bind_addr: SocketAddr = config.bind_addr.parse()?;
    let tcp_listener = tokio::net::TcpListener::bind(bind_addr).await?;
    info!(addr = %bind_addr, "zeroclaw HTTP/gRPC-Web listening on TCP");

    let axum_app = build_axum_app(loader.clone());
    let tcp_server = axum::serve(tcp_listener, axum_app);

    // Rebind task: when a new bind address is requested, restart the TCP server.
    // The current implementation starts the initial TCP server; subsequent
    // rebinds require a restart to keep the listener lifecycle simple and safe.
    let rebind_task = tokio::spawn(async move {
        while let Some(new_bind) = rebind_rx.recv().await {
            info!(new_bind = %new_bind, "D-Bus rebind request received; will be honored on next restart");
        }
    });

    let (unix_result, tcp_result) = tokio::join!(tonic_server, tcp_server);
    let _ = rebind_task.await;
    unix_result.map_err(|e| anyhow::anyhow!("Unix server error: {}", e))?;
    tcp_result.map_err(|e| anyhow::anyhow!("TCP server error: {}", e))
}

//! SchemaLoader — reads the plugin-owned zeroclaw schema JSON from tmpfs.
//!
//! The zeroclaw plugin in `op-plugins` is the sole writer of
//! `/dev/shm/opdbus/schemas/zeroclaw.json`. This loader only reads and reloads
//! on `SIGHUP` or D-Bus mutation. Reloads are broadcast to `WatchSchema`
//! streams via a tokio broadcast channel.

use std::path::{Path, PathBuf};
use std::sync::{Arc, RwLock};
use std::time::Instant;

use tokio::sync::broadcast;
use tracing::{info, warn};

/// Event emitted to `WatchSchema` subscribers after a successful reload.
#[derive(Clone, Debug)]
pub struct SchemaReloadEvent {
    pub event_type: String,
}

/// Shared loader state for the zeroclaw Axum host.
#[derive(Clone)]
pub struct SchemaLoader {
    path: Arc<RwLock<PathBuf>>,
    schema: Arc<RwLock<serde_json::Value>>,
    reload_tx: broadcast::Sender<SchemaReloadEvent>,
    health_status: Arc<RwLock<String>>,
}

impl SchemaLoader {
    /// Create a loader and perform the initial read.
    ///
    /// Panics with a descriptive message if the plugin-owned schema file is
    /// absent. This is intentional: the plugin must start first.
    pub fn new(path: impl Into<PathBuf>) -> anyhow::Result<Self> {
        let path = Arc::new(RwLock::new(path.into()));
        let loader = Self {
            path,
            schema: Arc::new(RwLock::new(serde_json::Value::Null)),
            reload_tx: broadcast::channel(16).0,
            health_status: Arc::new(RwLock::new(String::from("ok"))),
        };
        loader.load()?;
        Ok(loader)
    }

    /// Synchronous load used by `new()` for the initial read.
    ///
    /// Logs a warning if the operation exceeds the 50 ms budget.
    pub fn load(&self) -> anyhow::Result<()> {
        let start = Instant::now();
        let path = self.path.read().unwrap().clone();
        let bytes = std::fs::read(&path).map_err(|e| {
            anyhow::anyhow!(
                "zeroclaw schema file not readable at {}: {}. \
                 Ensure the zeroclaw plugin has started and written the file first.",
                path.display(),
                e
            )
        })?;
        Self::parse_and_store(self, &bytes, start, &path)
    }

    /// Asynchronous reload used by `SIGHUP` and the D-Bus object.
    pub async fn reload(&self) -> anyhow::Result<()> {
        let start = Instant::now();
        let path = self.path.read().unwrap().clone();
        let bytes = tokio::fs::read(&path).await.map_err(|e| {
            anyhow::anyhow!(
                "zeroclaw schema file not readable at {}: {}. \
                 Ensure the zeroclaw plugin has started and written the file first.",
                path.display(),
                e
            )
        })?;
        tokio::task::spawn_blocking({
            let loader = self.clone();
            let path = path.clone();
            move || Self::parse_and_store(&loader, &bytes, start, &path)
        })
        .await
        .map_err(|e| anyhow::anyhow!("reload task panicked: {}", e))?
    }

    fn parse_and_store(&self, bytes: &[u8], start: Instant, path: &Path) -> anyhow::Result<()> {
        let text = std::str::from_utf8(bytes).map_err(|e| {
            anyhow::anyhow!(
                "zeroclaw schema file at {} is not valid UTF-8: {}",
                path.display(),
                e
            )
        })?;
        let value: serde_json::Value = serde_json::from_str(text).map_err(|e| {
            anyhow::anyhow!(
                "zeroclaw schema file at {} is not valid JSON: {}",
                path.display(),
                e
            )
        })?;

        {
            let mut schema = self.schema.write().unwrap();
            *schema = value;
        }

        let elapsed = start.elapsed();
        if elapsed > std::time::Duration::from_millis(50) {
            warn!(
                elapsed_ms = elapsed.as_millis(),
                "zeroclaw schema reload exceeded 50 ms budget"
            );
        } else {
            info!(elapsed_ms = elapsed.as_millis(), "zeroclaw schema loaded");
        }

        let mut health = self.health_status.write().unwrap();
        *health = "ok".to_string();

        Ok(())
    }

    /// Clone the current schema value.
    pub async fn get(&self) -> serde_json::Value {
        self.schema.read().unwrap().clone()
    }

    /// Return the configured schema file path.
    pub fn path(&self) -> PathBuf {
        self.path.read().unwrap().clone()
    }

    /// Update the schema file path; the next `load()` will read from the new path.
    pub fn set_path(&self, path: impl Into<PathBuf>) {
        let mut p = self.path.write().unwrap();
        *p = path.into();
    }

    /// Return a handle to the reload broadcast channel.
    pub fn reload_tx(&self) -> broadcast::Sender<SchemaReloadEvent> {
        self.reload_tx.clone()
    }

    /// Return the current health status string.
    pub async fn health_status(&self) -> String {
        self.health_status.read().unwrap().clone()
    }

    /// Set health status (used by the D-Bus object and server startup).
    pub async fn set_health_status(&self, status: String) {
        let mut h = self.health_status.write().unwrap();
        *h = status;
    }

    /// Spawn a task that reloads the schema on `SIGHUP` and broadcasts the
    /// `evt.service.zeroclaw-schema.reloaded@v1` event.
    pub fn watch_sighup(self: Arc<Self>) -> tokio::task::JoinHandle<()> {
        tokio::spawn(async move {
            let mut sig =
                match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::hangup()) {
                    Ok(s) => s,
                    Err(e) => {
                        warn!(error = %e, "failed to install SIGHUP handler; manual reloads only");
                        return;
                    }
                };

            loop {
                sig.recv().await;
                info!(
                    subid = "evt.service.zeroclaw-schema.reloaded@v1",
                    "SIGHUP received"
                );
                match self.reload().await {
                    Ok(()) => {
                        let _ = self.reload_tx.send(SchemaReloadEvent {
                            event_type: "reload".to_string(),
                        });
                    }
                    Err(e) => {
                        warn!(error = %e, "SIGHUP reload failed");
                        let mut health = self.health_status.write().unwrap();
                        *health = e.to_string();
                    }
                }
            }
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;

    fn write_json(path: &Path, value: &serde_json::Value) {
        let mut file = std::fs::File::create(path).unwrap();
        file.write_all(serde_json::to_string(value).unwrap().as_bytes())
            .unwrap();
    }

    #[tokio::test]
    async fn should_load_schema_from_file() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("zeroclaw.json");
        let value = serde_json::json!({"name": "zeroclaw", "version": "1.0.0"});
        write_json(&path, &value);

        let loader = SchemaLoader::new(&path).unwrap();
        let loaded = loader.get().await;
        assert_eq!(loaded, value);
        assert_eq!(loader.health_status().await, "ok");
    }

    #[tokio::test]
    async fn should_reload_schema_on_sighup() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("zeroclaw.json");
        let initial = serde_json::json!({"name": "zeroclaw", "version": "1.0.0"});
        let updated = serde_json::json!({"name": "zeroclaw", "version": "2.0.0"});
        write_json(&path, &initial);

        let loader = Arc::new(SchemaLoader::new(&path).unwrap());
        let mut rx = loader.reload_tx().subscribe();

        // Simulate a reload by calling load directly and sending the event.
        loader.load().unwrap();
        let _ = loader.reload_tx.send(SchemaReloadEvent {
            event_type: "reload".to_string(),
        });

        // Verify the broadcast is received.
        let event = rx.recv().await.unwrap();
        assert_eq!(event.event_type, "reload");
        assert_eq!(loader.get().await, initial);

        // Update the file and reload again.
        write_json(&path, &updated);
        loader.load().unwrap();
        let _ = loader.reload_tx.send(SchemaReloadEvent {
            event_type: "reload".to_string(),
        });

        let event = rx.recv().await.unwrap();
        assert_eq!(event.event_type, "reload");
        assert_eq!(loader.get().await, updated);
    }
}

//! D-Bus object for the zeroclaw Axum host.
//!
//! Exposes `/org/opdbus/v1/services/zeroclaw_axum_host` with the runtime
//! configuration properties required by the spec. Writes to `BindAddr` or
//! `SchemaPath` trigger a reload signal; the server task picks it up and
//! reconfigures without restarting the process.

use std::sync::Arc;

use tokio::sync::{mpsc, RwLock};
use tracing::{info, warn};

use crate::schema_loader::SchemaLoader;

const DEFAULT_BIND_ADDR: &str = "0.0.0.0:8090";

/// D-Bus-facing configuration object for the zeroclaw Axum host.
#[derive(Clone)]
pub struct ZeroclawAxumHostObject {
    bind_addr: Arc<RwLock<String>>,
    schema_path: Arc<RwLock<String>>,
    reload_interval_secs: Arc<RwLock<u32>>,
    loader: Arc<SchemaLoader>,
    rebind_tx: mpsc::Sender<String>,
}

impl ZeroclawAxumHostObject {
    pub fn new(loader: Arc<SchemaLoader>, rebind_tx: mpsc::Sender<String>) -> anyhow::Result<Self> {
        let initial_path = loader.path().to_string_lossy().to_string();
        Ok(Self {
            bind_addr: Arc::new(RwLock::new(DEFAULT_BIND_ADDR.to_string())),
            schema_path: Arc::new(RwLock::new(initial_path)),
            reload_interval_secs: Arc::new(RwLock::new(0)),
            loader,
            rebind_tx,
        })
    }

    /// Read the current TCP bind address.
    async fn bind_addr_value(&self) -> String {
        self.bind_addr.read().await.clone()
    }

    /// Read the current plugin-owned schema file path.
    async fn schema_path_value(&self) -> String {
        self.schema_path.read().await.clone()
    }

    /// Read the current periodic reload interval in seconds.
    async fn reload_interval_value(&self) -> u32 {
        *self.reload_interval_secs.read().await
    }
}

#[zbus::interface(name = "org.opdbus.v1.ZeroclawAxumHost")]
impl ZeroclawAxumHostObject {
    #[zbus(property)]
    async fn bind_addr(&self) -> String {
        self.bind_addr_value().await
    }

    #[zbus(property)]
    async fn set_bind_addr(&self, value: String) {
        let mut addr = self.bind_addr.write().await;
        *addr = value.clone();
        drop(addr);
        info!(subid = "mut.service.zeroclaw-axum-host.reload@v1", new_bind = %value, "BindAddr changed; signaling rebind");
        if let Err(e) = self.rebind_tx.send(value).await {
            warn!(error = %e, "failed to send rebind request");
        }
    }

    #[zbus(property)]
    async fn schema_path(&self) -> String {
        self.schema_path_value().await
    }

    #[zbus(property)]
    async fn set_schema_path(&self, value: String) {
        let mut path = self.schema_path.write().await;
        *path = value.clone();
        drop(path);
        self.loader.set_path(value.clone());
        info!(subid = "mut.service.zeroclaw-axum-host.reload@v1", new_path = %value, "SchemaPath changed; reloading");
        if let Err(e) = self.loader.reload().await {
            warn!(error = %e, "schema path reload failed");
            self.loader.set_health_status(e.to_string()).await;
        }
    }

    #[zbus(property)]
    async fn reload_interval_secs(&self) -> u32 {
        self.reload_interval_value().await
    }

    #[zbus(property)]
    async fn set_reload_interval_secs(&self, value: u32) {
        let mut interval = self.reload_interval_secs.write().await;
        *interval = value;
    }

    #[zbus(property)]
    async fn health_status(&self) -> String {
        self.loader.health_status().await
    }
}

/// Register the zeroclaw Axum host object on the system bus.
pub async fn register_zeroclaw_host_object(
    object: ZeroclawAxumHostObject,
) -> anyhow::Result<zbus::Connection> {
    let connection = zbus::Connection::system().await?;
    connection
        .object_server()
        .at("/org/opdbus/v1/services/zeroclaw_axum_host", object)
        .await?;
    info!("registered /org/opdbus/v1/services/zeroclaw_axum_host");
    Ok(connection)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn should_expose_dbus_properties() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("zeroclaw.json");
        std::fs::write(&path, r#"{"name":"zeroclaw"}"#).unwrap();

        let loader = Arc::new(SchemaLoader::new(&path).unwrap());
        let (rebind_tx, _rebind_rx) = mpsc::channel(1);
        let obj = ZeroclawAxumHostObject::new(loader, rebind_tx).unwrap();

        assert_eq!(obj.bind_addr_value().await, "0.0.0.0:8090");
        assert_eq!(obj.schema_path_value().await, path.to_string_lossy());
        assert_eq!(obj.reload_interval_value().await, 0);
        assert_eq!(obj.health_status().await, "ok");
    }
}

